param([string]$BaseUrl='http://localhost:8080')
$ErrorActionPreference='Stop'
function A($a,$b,$n){if($a-ne$b){throw "$n expected=$b actual=$a"}}
function I($m,$p,$b=$null,$h=$null){$x=@{Method=$m;Uri="$BaseUrl$p";SkipHttpErrorCheck=$true};if($h){$x.Headers=$h};if($null-ne$b){$x.ContentType='application/json';$x.Body=$b|ConvertTo-Json -Compress};$r=Invoke-WebRequest @x;[pscustomobject]@{s=[int]$r.StatusCode;j=$r.Content|ConvertFrom-Json}}
$u="sec_timeout_$(Get-Random -Minimum 100000 -Maximum 999999)";$r=I POST '/api/auth/register' @{username=$u;password='SecTimeout_2026'};$h=@{Authorization="Bearer $($r.j.data.token)"};$a=I POST '/api/addresses' @{receiverName='Timeout';phone='13800138000';province='上海市';city='上海市';district='浦东新区';detail='秒杀超时';defaultAddress=$true} $h
$p=(I GET '/api/catalog/products/1').j.data.stock;$s=(I GET '/api/seckill/activities/1/goods' $null $h).j.data[0].stock;$q=I POST '/api/seckill/goods/1/orders' @{addressId=$a.j.data.id} $h;for($i=0;$i-lt30;$i++){Start-Sleep -Milliseconds 200;$z=I GET '/api/seckill/goods/1/result' $null $h;if($z.j.data.status-eq'SUCCESS'){break}};for($i=0;$i-lt10;$i++){Start-Sleep -Seconds 1;$o=I GET "/api/orders/$($z.j.data.orderId)" $null $h;if($o.j.data.status-eq'CANCELLED'){break}};A $o.j.data.status 'CANCELLED' 'SEC-055';A (I GET '/api/catalog/products/1').j.data.stock $p 'SEC-056 product';A (I GET '/api/seckill/activities/1/goods' $null $h).j.data[0].stock $s 'SEC-056 seckill';$again=I POST '/api/seckill/goods/1/orders' @{addressId=$a.j.data.id} $h;A $again.s 200 'SEC-057';Write-Host 'PASS: seckill timeout lifecycle.'
